        FROM memory.operator_turn_chunks c
        JOIN scope s ON s.turn_id = c.turn_id
        GROUP BY c.turn_id ORDER BY 2 ASC LIMIT 100
    ) x
),
lex AS MATERIALIZED (
    SELECT turn_id, ROW_NUMBER() OVER (ORDER BY r DESC) AS rnk
    FROM (
        SELECT t.id AS turn_id,
               ts_rank_cd(t.search_tsv, to_tsquery('english','embedding|pipeline|pgvector|semantic|recall|fusion')) AS r
        FROM memory.operator_turns t
        JOIN scope s ON s.turn_id = t.id
        WHERE t.search_tsv @@ to_tsquery('english','embedding|pipeline|pgvector|semantic|recall|fusion')
        ORDER BY 2 DESC LIMIT 100
    ) x
),
turn_scores AS (
    SELECT u.turn_id,
           COALESCE(1.0/(20 + sem.rnk),0) + COALESCE(1.0/(20 + lex.rnk),0) AS fused,
           sem.rnk AS sem_rank, lex.rnk AS lex_rank
    FROM (SELECT turn_id FROM sem UNION SELECT turn_id FROM lex) u
    LEFT JOIN sem ON sem.turn_id = u.turn_id
    LEFT JOIN lex ON lex.turn_id = u.turn_id
),
evidence AS (
    SELECT ts.*, sc.session_id,
           ROW_NUMBER() OVER (PARTITION BY sc.session_id ORDER BY ts.fused DESC, sc.created_at DESC) AS turn_pos
    FROM turn_scores ts JOIN scope sc ON sc.turn_id = ts.turn_id
),
top_evidence AS (SELECT * FROM evidence WHERE turn_pos <= 5),
session_scores AS (
    SELECT session_id, SUM(fused / turn_pos) AS session_score, COUNT(*) AS evidence_turns
    FROM top_evidence GROUP BY session_id ORDER BY 2 DESC LIMIT 20
)
SELECT ss.session_score, ss.evidence_turns, s.session_uuid::text, s.title, s.last_seen, p.project_path,
       e.turn_id, e.turn_pos, e.fused, e.sem_rank, e.lex_rank
FROM session_scores ss
JOIN sessions.sessions s ON s.id = ss.session_id
JOIN projects.projects p ON p.id = s.project_id
JOIN top_evidence e ON e.session_id = ss.session_id
ORDER BY ss.session_score DESC, e.turn_pos ASC;
